<?php
declare(strict_types=1);
session_set_cookie_params(['httponly'=>true, 'samesite'=>'Lax']); session_start(); require_once __DIR__ . '/functions.php';
$page=$_GET['page']??(user()?'dashboard':'login');
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); try { $action=$_POST['action']??'';
  if($action==='register'){ $username=trim($_POST['username']??'');$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??''; if(strlen($username)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8)throw new RuntimeException('Enter a username, valid email, and password of at least 8 characters.'); db()->prepare('INSERT INTO users (username,email,password_hash) VALUES (?,?,?)')->execute([$username,$email,password_hash($password,PASSWORD_DEFAULT)]); flash('success','Account created. Please sign in.');redirect('?page=login'); }
  if($action==='login'){ $s=db()->prepare('SELECT * FROM users WHERE email=?');$s->execute([strtolower(trim($_POST['email']??''))]);$account=$s->fetch();if(!$account||!password_verify($_POST['password']??'',$account['password_hash']))throw new RuntimeException('Incorrect email or password.');session_regenerate_id(true);unset($account['password_hash']);$_SESSION['user']=$account;redirect('?page=dashboard'); }
  if($action==='logout'){session_unset();session_destroy();session_start();flash('success','You have signed out.');redirect('?page=login');}
  $u=require_login();
  if($action==='create_application'){db()->prepare('INSERT INTO applications (applicant_id) VALUES (?)')->execute([$u['id']]);$id=(int)db()->lastInsertId();log_action($id,(int)$u['id'],'CREATED','Application draft created.');redirect('?page=application&id='.$id);}
  if($action==='save_application'){ $id=(int)$_POST['id'];$app=application_for($id);if(!$app||$app['applicant_id']!=$u['id']||!in_array($app['status'],['DRAFT','RESUBMISSION_REQUESTED'],true))throw new RuntimeException('This application cannot be edited.');$fields=['full_name','date_of_birth','nationality','id_type','id_number','id_expiry','issuing_country'];$values=[];foreach($fields as $f)$values[]=trim($_POST[$f]??'')?:null;db()->prepare('UPDATE applications SET '.implode(',',array_map(fn($f)=>"$f=?",$fields)).' WHERE id=?')->execute([...$values,$id]);$permanent=trim($_POST['permanent_address']??'');$temporary=trim($_POST['temporary_address']??'');if(!$permanent)throw new RuntimeException('Permanent address is required.');db()->prepare('INSERT INTO addresses (user_id,permanent_address,temporary_address) VALUES (?,?,?) ON DUPLICATE KEY UPDATE permanent_address=VALUES(permanent_address),temporary_address=VALUES(temporary_address)')->execute([$u['id'],$permanent,$temporary?:null]);log_action($id,(int)$u['id'],'UPDATED','KYC information and addresses updated.');flash('success','Draft saved.');redirect('?page=application&id='.$id); }
  if($action==='upload_profile_document'){ $id=(int)$_POST['id'];$app=application_for($id);if(!$app||$app['applicant_id']!=$u['id']||!in_array($app['status'],['DRAFT','RESUBMISSION_REQUESTED'],true))throw new RuntimeException('This application cannot accept documents.');$table=$_POST['table']??'';$column=$_POST['column']??'';save_user_document((int)$u['id'],$table,$column,$_FILES['document']??[]);log_action($id,(int)$u['id'],'DOCUMENT_UPLOADED',str_replace('_',' ',$column).' uploaded.');flash('success','Document uploaded.');redirect('?page=application&id='.$id); }
  if($action==='submit'){ $id=(int)$_POST['id'];$app=application_for($id);if(!$app||$app['applicant_id']!=$u['id']||!in_array($app['status'],['DRAFT','RESUBMISSION_REQUESTED'],true))throw new RuntimeException('This application cannot be submitted.');foreach(['full_name','date_of_birth','nationality','id_type','id_number','permanent_address'] as $f)if(!$app[$f])throw new RuntimeException('Complete personal details and permanent address before submitting.');db()->prepare("UPDATE applications SET status='SUBMITTED' WHERE id=?")->execute([$id]);log_action($id,(int)$u['id'],'SUBMITTED','Application submitted for review.');flash('success','Application submitted for review.');redirect('?page=application&id='.$id); }
  if($action==='review'){require_role(['REVIEWER','ADMIN']);$id=(int)$_POST['id'];$app=application_for($id);if(!$app||!in_array($app['status'],['SUBMITTED','UNDER_REVIEW'],true))throw new RuntimeException('This application is not awaiting review.');$decision=$_POST['decision']??'';$map=['approve'=>'APPROVED','reject'=>'REJECTED','resubmit'=>'RESUBMISSION_REQUESTED'];if(!isset($map[$decision]))throw new RuntimeException('Choose a review decision.');$notes=trim($_POST['review_notes']??'');if($decision!=='approve'&&!$notes)throw new RuntimeException('Provide notes for rejection or resubmission.');db()->prepare('UPDATE applications SET status=?,reviewer_id=?,review_notes=?,reviewed_at=NOW() WHERE id=?')->execute([$map[$decision],$u['id'],$notes,$id]);log_action($id,(int)$u['id'],'REVIEWED',format_status($map[$decision]).($notes?': '.$notes:''));flash('success','Review decision saved.');redirect('?page=application&id='.$id); }
}catch(PDOException $e){flash('error',$e->getCode()==='23000'?'That email address is already registered.':'Database error. Import the new install.sql schema.');redirect('?page='.$page);}catch(Throwable $e){flash('error',$e->getMessage());redirect('?page='.$page.(!empty($_POST['id'])?'&id='.(int)$_POST['id']:''));}}
function header_html(string $title):void{$u=user();?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · <?=APP_NAME?></title><link rel="stylesheet" href="assets/style.css"></head><body><header><a class="brand" href="?page=dashboard">KYC<span>Verify</span></a><?php if($u):?><nav><a href="?page=dashboard">Dashboard</a><a href="?page=applications">Applications</a><?php if(is_reviewer()):?><a href="?page=review">Review queue</a><?php endif?><span class="user"><?=e($u['username'])?><small><?=e($u['role'])?></small></span><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=csrf()?>"><button class="link" name="action" value="logout">Sign out</button></form></nav><?php endif?></header><main><?php foreach(flashes()as$f):?><div class="flash <?=$f['type']?>"><?=e($f['message'])?></div><?php endforeach?><?php }
function footer_html():void{?></main><footer>Secure application verification · Local PHP/MySQL edition</footer></body></html><?php }function badge(string $s):string{return '<span class="badge '.status_class($s).'">'.e(format_status($s)).'</span>';}function document_link(?string $file,int $uid):string{return $file?'<a href="uploads/users/'.$uid.'/'.rawurlencode($file).'" target="_blank">View uploaded document</a>':'<span class="muted">Not uploaded</span>';}
if($page==='login'&&!user()){header_html('Sign in');?><section class="auth"><div><p class="eyebrow">APPLICATION VERIFICATION</p><h1>Know your customer, with clarity.</h1><p>Submit identity, address, education, and government documents securely.</p></div><form method="post" class="card"><h2>Welcome back</h2><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="login"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button>Sign in</button><p class="muted">New here? <a href="?page=register">Create an account</a></p></form></section><?php footer_html();exit;}
if($page==='register'&&!user()){header_html('Create account');?><section class="auth"><div><p class="eyebrow">START YOUR APPLICATION</p><h1>Verification begins here.</h1><p>Your profile stores the documents required for KYC verification.</p></div><form method="post" class="card"><h2>Create account</h2><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="register"><label>Username<input name="username" required maxlength="120"></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="8" required></label><button>Create account</button><p class="muted">Already registered? <a href="?page=login">Sign in</a></p></form></section><?php footer_html();exit;}
$u=require_login();header_html(ucfirst($page));
if($page==='dashboard'){$s=db()->prepare('SELECT status,COUNT(*) total FROM applications WHERE applicant_id=? GROUP BY status');$s->execute([$u['id']]);$stats=$s->fetchAll();?><div class="hero"><div><p class="eyebrow">YOUR VERIFICATION</p><h1>Hello, <?=e($u['username'])?>.</h1><p><?=is_reviewer()?'Manage applications awaiting a decision.':'Create, complete, and monitor your KYC applications.'?></p></div><a class="button" href="?page=applications">View applications</a></div><div class="stats"><?php foreach($stats as$x):?><div class="stat"><strong><?=$x['total']?></strong><span><?=e(format_status($x['status']))?></span></div><?php endforeach?><?php if(!$stats):?><div class="empty">No applications yet. Start one from the applications page.</div><?php endif?></div><?php if(is_reviewer()):$n=db()->query("SELECT COUNT(*) FROM applications WHERE status IN ('SUBMITTED','UNDER_REVIEW')")->fetchColumn();?><section class="card callout"><h2><?=$n?> applications need review</h2><a class="button" href="?page=review">Open review queue</a></section><?php endif;}
elseif($page==='applications'){$sql=is_reviewer()?'SELECT a.*,u.username applicant_name FROM applications a JOIN users u ON u.id=a.applicant_id ORDER BY a.updated_at DESC':'SELECT a.*,u.username applicant_name FROM applications a JOIN users u ON u.id=a.applicant_id WHERE a.applicant_id=? ORDER BY a.updated_at DESC';$s=db()->prepare($sql);$s->execute(is_reviewer()?[]:[$u['id']]);$apps=$s->fetchAll();?><div class="hero compact"><div><p class="eyebrow"><?=is_reviewer()?'ALL APPLICATIONS':'MY APPLICATIONS'?></p><h1>Applications</h1></div><?php if($u['role']==='APPLICANT'):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><button name="action" value="create_application">New application</button></form><?php endif?></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Applicant</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody><?php foreach($apps as$a):?><tr><td>#<?=$a['id']?></td><td><?=e($a['applicant_name'])?></td><td><?=badge($a['status'])?></td><td><?=e(date('d M Y, H:i',strtotime($a['updated_at'])))?></td><td><a href="?page=application&id=<?=$a['id']?>">Open →</a></td></tr><?php endforeach?><?php if(!$apps):?><tr><td colspan="5" class="empty">No applications found.</td></tr><?php endif?></tbody></table></div>
<?php }elseif($page==='review'){require_role(['REVIEWER','ADMIN']);$apps=db()->query("SELECT a.*,u.username applicant_name FROM applications a JOIN users u ON u.id=a.applicant_id WHERE a.status IN ('SUBMITTED','UNDER_REVIEW') ORDER BY a.created_at ASC")->fetchAll();?><div class="hero compact"><div><p class="eyebrow">REVIEW WORKSPACE</p><h1>Review queue</h1></div></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Applicant</th><th>Submitted</th><th></th></tr></thead><tbody><?php foreach($apps as$a):?><tr><td>#<?=$a['id']?></td><td><?=e($a['applicant_name'])?></td><td><?=e(date('d M Y, H:i',strtotime($a['updated_at'])))?></td><td><a class="button small" href="?page=application&id=<?=$a['id']?>">Review</a></td></tr><?php endforeach?><?php if(!$apps):?><tr><td colspan="4" class="empty">The queue is clear.</td></tr><?php endif?></tbody></table></div>
<?php }elseif($page==='application'){$id=(int)($_GET['id']??0);$app=application_for($id);if(!$app||!can_access($app,$u)){http_response_code(404);echo'<h1>Application not found</h1>';footer_html();exit;}$s=db()->prepare('SELECT * FROM education WHERE user_id=?');$s->execute([$app['applicant_id']]);$education=$s->fetch()?:[];$s=db()->prepare('SELECT * FROM additional_documents WHERE user_id=?');$s->execute([$app['applicant_id']]);$additional=$s->fetch()?:[];$s=db()->prepare('SELECT l.*,u.username actor_name FROM audit_logs l LEFT JOIN users u ON u.id=l.actor_id WHERE application_id=? ORDER BY l.created_at DESC');$s->execute([$id]);$audit=$s->fetchAll();$editable=$app['applicant_id']==$u['id']&&in_array($app['status'],['DRAFT','RESUBMISSION_REQUESTED'],true);?><div class="hero compact"><div><p class="eyebrow">APPLICATION #<?=$id?></p><h1><?=e($app['full_name']?:'New application')?> <?=badge($app['status'])?></h1><p>Applicant: <?=e($app['applicant_name'])?></p></div></div><?php if($editable):?><form method="post" class="card form-grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_application"><input type="hidden" name="id" value="<?=$id?>"><h2>Personal and identity details</h2><label>Full legal name *<input name="full_name" value="<?=e($app['full_name'])?>" required></label><label>Date of birth *<input type="date" name="date_of_birth" value="<?=e($app['date_of_birth'])?>" required></label><label>Nationality *<input name="nationality" value="<?=e($app['nationality'])?>" required></label><label>ID type *<select name="id_type" required><option value="">Select type</option><?php foreach(['Citizenship','Passport','Driver License','National ID']as$v):?><option <?=$app['id_type']===$v?'selected':''?>><?=$v?></option><?php endforeach?></select></label><label>ID number *<input name="id_number" value="<?=e($app['id_number'])?>" required></label><label>ID expiry<input type="date" name="id_expiry" value="<?=e($app['id_expiry'])?>"></label><label>Issuing country<input name="issuing_country" value="<?=e($app['issuing_country'])?>"></label><div></div><h2>Address</h2><label>Permanent address *<textarea name="permanent_address" required><?=e($app['permanent_address'])?></textarea></label><label>Temporary address<textarea name="temporary_address"><?=e($app['temporary_address'])?></textarea></label><div><button>Save draft</button></div></form><?php else:?><section class="card details"><h2>Personal and identity details</h2><dl><dt>Name</dt><dd><?=e($app['full_name'])?></dd><dt>Date of birth</dt><dd><?=e($app['date_of_birth'])?></dd><dt>Nationality</dt><dd><?=e($app['nationality'])?></dd><dt>Identification</dt><dd><?=e($app['id_type'].' · '.$app['id_number'])?></dd><dt>Permanent address</dt><dd><?=nl2br(e($app['permanent_address']))?></dd><dt>Temporary address</dt><dd><?=nl2br(e($app['temporary_address']))?></dd></dl><?php if($app['review_notes']):?><div class="notes"><strong>Reviewer notes</strong><br><?=nl2br(e($app['review_notes']))?></div><?php endif?></section><?php endif?><section class="card"><h2>Education documents</h2><div class="documents"><?php foreach(['see_document'=>'SEE document','slc_document'=>'SLC document','graduate_document'=>'Graduate document']as$column=>$label):?><div class="document"><strong><?=$label?></strong><?=document_link($education[$column]??null,(int)$app['applicant_id'])?><?php if($editable):?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="upload_profile_document"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="table" value="education"><input type="hidden" name="column" value="<?=$column?>"><input type="file" name="document" accept=".jpg,.jpeg,.png,.pdf" required><button class="small">Upload</button></form><?php endif?></div><?php endforeach?></div></section><section class="card"><h2>Additional documents</h2><div class="documents"><?php foreach(['citizenship_document'=>'Citizenship','passport_document'=>'Passport','license_document'=>'License']as$column=>$label):?><div class="document"><strong><?=$label?></strong><?=document_link($additional[$column]??null,(int)$app['applicant_id'])?><?php if($editable):?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="upload_profile_document"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="table" value="additional_documents"><input type="hidden" name="column" value="<?=$column?>"><input type="file" name="document" accept=".jpg,.jpeg,.png,.pdf" required><button class="small">Upload</button></form><?php endif?></div><?php endforeach?></div><p class="muted">JPG, PNG, or PDF · maximum 5 MB.</p></section><?php if($editable):?><form method="post" class="card action-card"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="submit"><input type="hidden" name="id" value="<?=$id?>"><div><h2>Ready for review?</h2><p>Once submitted, your details are locked while a reviewer checks them.</p></div><button>Submit application</button></form><?php endif;if(is_reviewer()&&in_array($app['status'],['SUBMITTED','UNDER_REVIEW'],true)):?><form method="post" class="card review"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="review"><input type="hidden" name="id" value="<?=$id?>"><h2>Review decision</h2><label>Notes (required for reject/resubmit)<textarea name="review_notes" rows="4"></textarea></label><div class="decision"><button name="decision" value="approve" class="approve">Approve</button><button name="decision" value="resubmit" class="warning">Request changes</button><button name="decision" value="reject" class="danger">Reject</button></div></form><?php endif?><section class="card"><h2>Audit trail</h2><div class="timeline"><?php foreach($audit as$l):?><div><strong><?=e(format_status($l['action']))?></strong><span><?=e($l['detail'])?></span><small><?=e($l['actor_name']?:'System')?> · <?=e(date('d M Y, H:i',strtotime($l['created_at'])))?></small></div><?php endforeach?></div></section><?php } else {http_response_code(404);echo'<h1>Page not found</h1>';}footer_html();
